window.STORY_CHAPTERS["cae68596eec8d37ec"]={"id":"cae68596eec8d37ec","lines":[{"uid":"talk.vc.home_event_sortiliena_3#originalText","id":"talk.vc.home_event_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你手里拿着真多点心呢。这些全部，都是那什么情人节的礼物吗！？","en":"You certainly have lots of candy. Was all of it because of that \"Valentine's\" day of yours?!","ja":"お前はたくさん菓子を持っているなそれが全部、バレンタインとやらの贈り物なのか!?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_4#originalText","id":"talk.vc.home_event_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"欢庆女子成长的祭典啊？如果儿童时期有这个活动，想必我当时也会欣喜若狂吧。","en":"A festival to celebrate girls growing up? I'm sure I would have loved such a festival as a child.","ja":"女子の成長を喜ぶ祭りか子どもの頃にあったら私もきっと大喜びしていただろう"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_5#originalText","id":"talk.vc.home_event_sortiliena_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"这就是你的回礼啊。再让我观摩一次剑技也很好啊……不过，我很开心。","en":"So, this is your thank-you gift? I would have been satisfied seeing you fight again, but...I like this gift, too.","ja":"これが前のお返しかまた剣技を見せてくれてもよかったぞ……だが、うれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_6#originalText","id":"talk.vc.home_event_sortiliena_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我们很不习惯骗人，因为有禁忌目录在。","en":"We aren't accustomed to lying. It goes against the Taboo Index.","ja":"私たちは、嘘を付くのに慣れていないんだ禁忌目録があるからな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_7#originalText","id":"talk.vc.home_event_sortiliena_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"长期休假啊……那我们来趟外宿修行吧？可以不用在意时间尽情过招喔。","en":"A long vacation, you say? Then, perhaps we should travel somewhere to train? We can duel all day, without worrying about time.","ja":"長期の安息日か……ならば、泊りがけで修行するか時間を気にせずに立ち合えるぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_8#originalText","id":"talk.vc.home_event_sortiliena_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"在雨天有雨天的战斗方式。来，跟我到外面。","en":"There is a special way of fighting on rainy days. Come, let's go outside to practice.","ja":"雨の日には、雨の日の戦い方があるさあ、外へ行くぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_9#originalText","id":"talk.vc.home_event_sortiliena_9","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"一年一次的相会啊……如果是被高墙分隔两侧的情侣，或许也会是如此吧。","en":"The lovers only meet once a year? When separated by a wall, I suppose that is inevitable.","ja":"年に一度の逢瀬か……壁で隔てられた恋人同士ならそうなってしまうかもしれないな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_10#originalText","id":"talk.vc.home_event_sortiliena_10","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"在海里游泳……果然还是有点恐怖啊。不晓得海里究竟有什么东西……","en":"Swimming in the ocean... That still terrifies me a little. There's no telling what's under the water.","ja":"海で泳ぐのは……やはり少し怖いな海中には何がいるのか……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_11#originalText","id":"talk.vc.home_event_sortiliena_11","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"长假也要结束了。如何运用这段期间，我认为非常重要。","en":"The long vacation is coming to an end. I think it's vital to make the most out of one's time off.","ja":"長期の安息日も終わりだなこの時期の過ごし方はとても大事だと思う"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_12#originalText","id":"talk.vc.home_event_sortiliena_12","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"像这样悠闲地眺望月亮，就会蓦然想起至今发生的事情。","en":"When I stare at the moon like this, I start remembering things from my past.","ja":"こうしてゆっくり月を眺めると、ふと今までのことを思い出すんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_13#originalText","id":"talk.vc.home_event_sortiliena_13","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我才不穿那种东西！要穿你自己穿！","en":"I am not wearing that...thing! If you want to dress up, dress up alone!","ja":"私はそんなもの着ないぞ! 着るならお前ひとりでやれ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_sortiliena_15#originalText","id":"talk.vc.home_event_sortiliena_15","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"要交换礼物啊？这很考验送礼者的感性呢……","en":"So, you exchange gifts? One can read a lot into another person's feelings by examining their gift...","ja":"贈り物を交換するのかそれはその人の感性が問われるな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_1#originalText","id":"talk.vc.home_event_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"新年快乐！希望大家今年也身体健康，平平安安。","en":"Happy New Year! I hope everyone has a happy and healthy year!","ja":"あけましておめでとう今年も一年、みんな健康で無事に過ごせますように"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_2#originalText","id":"talk.vc.home_event_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"惠方卷啊，就是没办法一口气吃完对吧。","en":"Setsubun sushi rolls are always impossible to eat in one bite.","ja":"恵方巻きって、全部いっぺんには食べきれないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_3#originalText","id":"talk.vc.home_event_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我今年试着做成巧克力饼干。这样玩游戏或念书的时候，就能轻松食用了嘛。","en":"I made you a chocolate cake this year. This way, you can easily sneak in bites while you're studying or gaming.","ja":"今年はチョコクッキーにしてみたんだこれなら、ゲームとかお勉強の時でも簡単につまめるでしょ? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_4#originalText","id":"talk.vc.home_event_suguha_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"因为今天的主角是女孩子，所以我可以尽情撒娇吧？","en":"Today is the day where girls are the star, so shower us with affection, okay?","ja":"今日は女の子が主役の日だからたくさん甘えていいよね? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_5#originalText","id":"talk.vc.home_event_suguha_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"嘿嘿，谢谢你。收到回礼果然会很开心呢。","en":"Hehe, thank you. I do love getting thank-you gifts.","ja":"えへへ、ありがとうやっぱり、お返しもらえるとうれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_6#originalText","id":"talk.vc.home_event_suguha_6","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我一直在想怎样才能骗到你，结果昨天就熬夜了……呼哇……","en":"I was trying to come up with a good April Fool's prank, and before I knew it, I'd stayed up all night.","ja":"どんな嘘で驚かせようかって考えてたら、昨日夜更かししちゃって……ふわあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_7#originalText","id":"talk.vc.home_event_suguha_7","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"连假的时候大家一起外宿也不错呢。也邀请亚丝娜和莉兹她们吧。","en":"I'd love to go away somewhere on vacation with the gang. You know, like Asuna and Liz.","ja":"連休は、みんなでお泊り旅行もいいよね。アスナさんとか、リズさんたちも誘って"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_8#originalText","id":"talk.vc.home_event_suguha_8","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"好潮湿啊。洗好的衣服也晾不干，夏天可不可以快点来啊？","en":"It's really humid today, huh? This laundry won't dry on the line. Can it be summer already?","ja":"なんか蒸し蒸しするね洗濯物も乾かないし早く夏にならないかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_9#originalText","id":"talk.vc.home_event_suguha_9","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"听说今天晚上会有七夕烟火呢！欸，我们一起去看嘛。","en":"I hear there's going to be fireworks tonight for Tanabata! Let's go see them!","ja":"今日の七夕、夜は花火があるんだって! ねえ、一緒に見に行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_10#originalText","id":"talk.vc.home_event_suguha_10","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"嘿嘿，我买了新泳装，所以大家一起去游泳池吧！","en":"Hehe, I bought a new swimsuit, so let's all go swimming!","ja":"へへ、新しい水着を買ったからみんなでプールに行こうよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_11#originalText","id":"talk.vc.home_event_suguha_11","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"欢乐的暑假也结束了呢，明天开始又要上学啊～","en":"It's sad summer vacation is almost over. Agh. I have to go to school tomorrow.","ja":"楽しい夏休みも終わっちゃうね明日から、また学校かあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_12#originalText","id":"talk.vc.home_event_suguha_12","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"我们曾经一起把团子都吃光，结果就挨骂了呢。好怀念啊。","en":"Remember when we were kids and ate all the rice cakes and got yelled at? Those were the days, huh?","ja":"昔、いっしょにお団子全部食べちゃって、怒られたよね懐かしいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_13#originalText","id":"talk.vc.home_event_suguha_13","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"小时候，我们有一起装扮成鬼怪，在附近邻居间打转呢。那时候真好玩。","en":"I remember wandering around the neighborhood dressed as ghosts when we were little. That was so much fun.","ja":"小さい頃は、一緒にお化けの格好でご近所を回ったよねすごく楽しかった"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_14#originalText","id":"talk.vc.home_event_suguha_14","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"今天是令人忘不了的日子唷。……不过，你还是回来了，所以我现在才有办法不哭。","en":"Today is a day I'll never forget. But...you came back home in the end. So I don't have to cry this year.","ja":"今日は忘れられない日だよ……でも、帰ってきてくれたからだから、今は泣かずにいられるの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_suguha_15#originalText","id":"talk.vc.home_event_suguha_15","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"圣诞快乐！今天有很多好吃的，你要多吃一点喔。","en":"Merry Christmas! We've got a big feast, so loosen your belt!","ja":"メリークリスマス! 今日はご馳走たっくさんだからいっぱい食べてね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_1#originalText","id":"talk.vc.home_event_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"能跟学长一起迎接新年，让我非常开心。","en":"It is an honor to ring in the new year with you, sir.","ja":"新たな年を先輩と一緒に迎えることができてとてもうれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_2#originalText","id":"talk.vc.home_event_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"那副面具怎么了吗？那也跟《艾恩葛朗特流》有关吗？","en":"Why are you wearing that mask? Is it an Aincrad tradition?","ja":"そのお面はどうしたんですか? それも《アインクラッド流》なのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_3#originalText","id":"talk.vc.home_event_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，我做的点心……味道如何呢？","en":"Do you like the candy I made you?","ja":"先輩、あたしの作ったお菓子……お味はどうでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_4#originalText","id":"talk.vc.home_event_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这个人偶的衣服……很像东方的服饰呢。是那边的风俗习惯吗？","en":"The clothing on these dolls... It looks Eastern. Is this an Eastern custom?","ja":"このお人形の服……東方の衣装に似ていますがそちらの風習でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_5#originalText","id":"talk.vc.home_event_tiese_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"这是要给我的吗？……我的心意传达给您了呢。谢谢您，学长。","en":"This gift is...for me? Oh! You're thanking me for the candy. Well, thank you, too, Mentor!","ja":"これを、あたしに? ……想いが届いたんですねありがとうございます、先輩"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_6#originalText","id":"talk.vc.home_event_tiese_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"骗人这件事，我实在……说伤害人的谎话，是抵触禁忌目录的。","en":"I'm not comfortable with lying, lies hurt others. The Taboo Index says so.","ja":"嘘を付くのは、あまり……人を傷つける嘘は禁忌目録に抵触してしまうので"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_7#originalText","id":"talk.vc.home_event_tiese_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"就算在安息日，随侍仍是随侍，所以我每天都会来的。","en":"Even on a day of rest, a page must still take care of her master.","ja":"安息日でも傍付きは傍付きですから、毎日伺いますね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_8#originalText","id":"talk.vc.home_event_tiese_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"雨下个不停呢。希望不会影响农作物的生长。","en":"The rain just keeps pouring. I hope it doesn't damage the crops.","ja":"ずっと雨が降っていますね作物の生育に、影響が出ないといいのですが"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_9#originalText","id":"talk.vc.home_event_tiese_9","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"写下愿望，传达给天上的神明……非常不可思议，却是个很棒的风俗呢。","en":"You write down wishes on slips of paper and offer them to the gods? That's an odd custom, but I like it.","ja":"願いを書いて、空の神様に届ける……不思議ですが素敵な風習ですね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_10#originalText","id":"talk.vc.home_event_tiese_10","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"夏至祭典就快到了呢。到时学院也会放假，要不要一起去看看呢？","en":"The Summer Festival is upon us. The Academy is taking a holiday then, so... would you like to go to the Festival with me?","ja":"夏至祭が迫ってきましたね学院もお休みですから一緒に見学しませんか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_11#originalText","id":"talk.vc.home_event_tiese_11","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我已经做完作业了。因为我认为，不按部就班进行，会写不完……","en":"I already finished my school work. I knew I needed to be systematic, or I would never finish on time.","ja":"課題ならもう終わりました計画的にやらないと終わらないと思ったので……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_12#originalText","id":"talk.vc.home_event_tiese_12","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"月亮好大啊。跟学长一起看，感觉月亮更美了。","en":"What a big moon! Looking at it with you like this, it seems even more beautiful.","ja":"大きな月ですね先輩と一緒に見るといつもより美しい気がします"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_13#originalText","id":"talk.vc.home_event_tiese_13","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"要我穿这个吗？虽、虽然的确没有违反禁忌目录……","en":"You want me to wear this? W-well, at least it doesn't break the Taboo Index.","ja":"これを、着るんですか? た、確かに禁忌目録には違反していないですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_tiese_15#originalText","id":"talk.vc.home_event_tiese_15","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"今天是交换礼物的日子，没有错吧？我可以跟学长交换吗？","en":"Today is a day of exchanging gifts, yes? Is it okay if we exchange gifts, too?","ja":"今日は贈り物を交換する日なんですよね? 先輩と交換しても、いいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_1#originalText","id":"talk.vc.home_event_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"欸，你的汤里要放几块年糕？","en":"Hey, how much mochi are you putting in the New Year's soup?","ja":"ねえ、お雑煮にはお餅いくつ入れる?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_2#originalText","id":"talk.vc.home_event_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"来，努力把豆子吃下去吧！因为这样就能变健康！","en":"Okay, let's eat all the beans! They're supposed to make you healthier, right?","ja":"さあ、頑張って豆を食べよう! だって、健康になれるんでしょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_3#originalText","id":"talk.vc.home_event_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"在今天啊，女孩子看起来都很忙呢～","en":"All the girls are so hyper today.","ja":"今日は、女の子たちはみんな忙しそうだねー"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_4#originalText","id":"talk.vc.home_event_yuuki_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"天皇人偶有带刀，不过你不觉得，这给皇后拿也不错吗？","en":"The prince doll is holding a sword in this display, but don't you think the princess should also have a sword?","ja":"お内裏様って刀を持ってるけどこれってお雛様が持ってもいいと思わない? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_5#originalText","id":"talk.vc.home_event_yuuki_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我也有给过白色情人节的回礼喔。虽然，收就没什么经验了。","en":"I've given gifts for White Day, but I've never really received them.","ja":"ボクも、ホワイトデーのお返しあげたことあるよもらったことは、あんまりないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_6#originalText","id":"talk.vc.home_event_yuuki_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"因为今天是愚人节，要不要试着前后卫对调看看啊？","en":"Since it's April Fool's Day, do you wanna reverse our advance-guard and rear-guard as a joke?","ja":"エイプリルフールだから前衛と後衛、交換してみようか? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_7#originalText","id":"talk.vc.home_event_yuuki_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"外宿！？你愿意跟我一起出门外宿吗！？","en":"Do you mean it?! Are we really going away on vacation together?!","ja":"お泊り!?一緒にお泊り行ってくれるの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_8#originalText","id":"talk.vc.home_event_yuuki_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"这个季节在哪个世界都一直在下雨呢我也喜欢雨喔因为可以遇到跟平常不一样的敌人","en":"It’s raining in every world during this season. I like the rain. You can meet all different kinds of enemies.","ja":"この季節はどの世界もずっと雨だねボク雨も好きだよいつもと違う敵に会えるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_9#originalText","id":"talk.vc.home_event_yuuki_9","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"可不可以一个人写好几张短签啊？想许的愿望，我可是有很多呢！","en":"Can I write down as many Tanabata wishes as I want? There are so many things I want to wish for!","ja":"短冊って、いくつ書いてもいいのかな? お願いしたいことたくさんあるんだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_10#originalText","id":"talk.vc.home_event_yuuki_10","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我想要去海边玩玩看打西瓜！可以使用剑技吗？","en":"I wanna go to the beach and play the watermelon smashing game! Do you think I can use a Sword Skill for that?","ja":"海に行ってスイカ割りとかやってみたい! ソードスキル使えるかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_11#originalText","id":"talk.vc.home_event_yuuki_11","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"大家差不多要开始上学了呢我也想去看看学校……","en":"Everyone will be starting school soon. I want to go, too...","ja":"みんなはそろそろ学校が始まるねボクも、行ってみたいなぁ……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_12#originalText","id":"talk.vc.home_event_yuuki_12","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"月亮居然这么明亮。你看，连你的头发都可以看得很清楚！","en":"Wow, I didn't know the moon could be so bright. Look at how shiny it's making your hair!","ja":"月ってこんなに明るいんだねほら、キミの髪もこんなにはっきり見える! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_13#originalText","id":"talk.vc.home_event_yuuki_13","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"既然你到我这来，那当然就要来场捣蛋对决啊！","en":"If you come to my door, there's gonna be nothing but tricks!","ja":"ボクのところに来たらもちろんイタズラ勝負だよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_event_yuuki_15#originalText","id":"talk.vc.home_event_yuuki_15","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"哇啊，好大的圣诞树～！我一直很憧憬这么大棵的树呢。","en":"Ooh, what a huge Christmas tree! I've always wanted to have a big tree like this.","ja":"うわあ、おっきいクリスマスツリー!こういう大きなツリー憧れてたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_administrator_1#originalText","id":"talk.vc.home_rank_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你看起来稍微气派了点呢。就照这样多努力吧。","en":"I see you're starting to look proud of yourself. Good. Keep encouraging yourself to do better.","ja":"少しは見栄えがするようになったわねその調子で励みなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_administrator_2#originalText","id":"talk.vc.home_rank_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你那点程度，还远不足以对抗《黑暗领域》的成员。","en":"You are still not powerful enough to combat forces from the Dark Territory.","ja":"まだまだ、その程度では《ダークテリトリー》の輩に対抗できないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_administrator_3#originalText","id":"talk.vc.home_rank_administrator_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"总算有能力成为上级骑士，你的程度差不多就在这吧。","en":"You are finally worthy of becoming an Integrity Knight.","ja":"やっと上級騎士になれる、と言ったところかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_administrator_4#originalText","id":"talk.vc.home_rank_administrator_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"……你确实变强了呢，或许有点危险呀。","en":"You have become quite strong indeed... It's a bit concerning.","ja":"……確かに強くなったわね少し危険かもしれないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_administrator_5#originalText","id":"talk.vc.home_rank_administrator_5","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"……你是不是强过头了呀？为防万一，或许有必要再调整一次呢。","en":"Perhaps you've become too strong... Maybe it's time to go back to the drawing board and readjust you.","ja":"……強くなりすぎたかしら万一に備えて、もう一度調整しておく必要があるかもね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_agil_1#originalText","id":"talk.vc.home_rank_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"升级啦？恭喜。","en":"Congrats on ranking up.","ja":"ランクアップか、おめでとう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_agil_2#originalText","id":"talk.vc.home_rank_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你是不是变强不少啊？真不愧是前攻略组呢。","en":"You got a lot stronger, didn't you? Well, you are a former Assault Team member.","ja":"ずいぶん強くなったんじゃないか?さすがは元攻略組だな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_agil_3#originalText","id":"talk.vc.home_rank_agil_3","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"又变强啦？呵呵，真可靠啊。","en":"You leveled-up again? Hehe, now I can feel safe at night.","ja":"また強くなったのかふふ、心強いぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_agil_4#originalText","id":"talk.vc.home_rank_agil_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我还是别跟你过招了吧，感觉不出胜算。","en":"I don't think I wanna fight you now. You'll probably beat me.","ja":"さすがに手合わせはやめておこうか勝てる気がしない"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_agil_5#originalText","id":"talk.vc.home_rank_agil_5","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你到底是打算变得多强啊？","en":"Jeez, just how much stronger are you gonna get?","ja":"どこまで強くなるんだ、お前は"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_1#originalText","id":"talk.vc.home_rank_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"稍微变强了呢，真是可喜。","en":"You have gotten a bit stronger. That is cause for celebration.","ja":"少しは強くなったようですね喜ばしいことです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_2#originalText","id":"talk.vc.home_rank_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"嗯……我们来比划一下吧。我越来越想确认你的实力了。","en":"Hm...let us have a duel. I suddenly want to test your abilities.","ja":"ふむ……少し立ち合ってみましょうお前の実力、確かめておきたくなりました"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_3#originalText","id":"talk.vc.home_rank_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这记攻击……我从中感受到你心灵的强韧。没想到你将自己锻炼到这种地步……","en":"The strength with which you strike... I can feel the determination in your heart. I am impressed by how hard you've trained.","ja":"この打ち込み……お前の心の強さを感じますここまで己を鍛えるとは……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_4#originalText","id":"talk.vc.home_rank_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"如今，恐怕连我也难以胜过你了。你那驱策自己钻研的态度值得嘉许。","en":"Victory will no longer come easily to me. Your self-improvement is worthy of praise.","ja":"もはや、私でも容易に勝つことは難しいでしょう。その自己研鑽称賛に値します"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_5#originalText","id":"talk.vc.home_rank_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我想，你正是解救人界的骑士。虽然只能一尽棉薄之力，今后我将会协助你。","en":"You are indeed a knight who will save the Human Realm. I shall assist you in any way I can.","ja":"お前こそ、人界を救う騎士でしょう私も力及ばずながら助力いたします"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_child_1#originalText","id":"talk.vc.home_rank_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"不知不觉间你变强了耶，以前我都不会输给你的说。","en":"You got stronger while I wasn't looking. And I used to be able to beat you in the past!","ja":"いつの間にか強くなったのね昔は私も負けなかったのに"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_child_2#originalText","id":"talk.vc.home_rank_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"啊～你又长高了吧！太狡猾了，居然偷跑！","en":"Heeey, you grew another inch! No fair! Don't leave me behind!","ja":"あー、また背が伸びたでしょ! ずるいわ、そんなに先に! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_child_3#originalText","id":"talk.vc.home_rank_alice_child_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"呵呵，既然你这么强，不论发生什么事，你都会保护我吧。","en":"Hehe, as strong as you've become, I know you'll protect me no matter what.","ja":"ふふ、こんなに強かったら何があっても私を守ってくれるわね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_child_4#originalText","id":"talk.vc.home_rank_alice_child_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"总觉得你判若两人了，这不是变得很帅气吗？……只有一点点啦。","en":"You've gotten so heroic, I almost didn't recognize you...","ja":"なんだか見違えちゃったかっこよくなったんじゃない……ちょっとだけね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_alice_child_5#originalText","id":"talk.vc.home_rank_alice_child_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"现在的你，一定连黑暗领域的恶鬼都能打倒喔！","en":"Even the Dark Territory's minions don't stand a chance against you now!","ja":"きっと今なら、ダークテリトリーの悪鬼だって倒せちゃうわね! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_argo_1#originalText","id":"talk.vc.home_rank_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"好厉害，你升级了呢。我的情报也多少有帮上你的忙吧？","en":"You leveled-up. Cool. Did my intel help you out?","ja":"ランクアップ、すごいじゃないカオレっちの情報も少しは役に立ったカナ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_argo_2#originalText","id":"talk.vc.home_rank_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你就照这个样子变强，然后多多帮我收集好情报回来吧。","en":"Good. Keep getting stronger and gather great info for me.","ja":"その調子で強くなっていい情報をたくさん集めてきてくれヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_argo_3#originalText","id":"talk.vc.home_rank_argo_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"我说啊，你有……高等头目的情报吧？","en":"So, hey... You must have some info on high level bosses by now, right?","ja":"なあなあ、高レベルボスの情報……持ってるんダロ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_argo_4#originalText","id":"talk.vc.home_rank_argo_4","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"一段时间没见面，你就变得那么厉害啦。吓了我一跳呢。","en":"You sure got a lot stronger while I wasn't looking. You surprised me.","ja":"しばらく見ない間にずいぶん腕を上げたんダナびっくりしたヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_argo_5#originalText","id":"talk.vc.home_rank_argo_5","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"嘿嘿，你变强了呢。感觉就像变强的是我自己一样，我很骄傲呢。","en":"Hehe. You sure got strong. I'm really proud of you.","ja":"へへ、強くなったナなんだか自分のことみたいに誇らしいヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_1#originalText","id":"talk.vc.home_rank_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"恭喜你升级！我也要加油了！","en":"Congrats on ranking up! Now I've got to catch up.","ja":"ランクアップおめでとう! わたしも頑張ろうっと! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_2#originalText","id":"talk.vc.home_rank_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你又变强啦？希望你不要留下我前进得太远。","en":"You got stronger yet again. Don't get too much better than me, okay?","ja":"また強くなっちゃったあんまり置いて行かないでほしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_3#originalText","id":"talk.vc.home_rank_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我们来庆祝升级吧！这可是值得纪念的日子呢。","en":"Let's celebrate your rank increase! Come on, it's a special day.","ja":"ランクアップのお祝いしましょう!だって、記念の日だもん"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_4#originalText","id":"talk.vc.home_rank_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你总是在我前面不远的地方，拉着我前行。","en":"You're always just a couple steps ahead of me, pushing me to better myself.","ja":"君はいつもわたしの少し前にいてわたしを引っ張っていってくれるんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_asuna_5#originalText","id":"talk.vc.home_rank_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我打从一开始就知道了喔。你是世界上最强的人。","en":"I knew it all along. You're the strongest guy in the world!","ja":"わたしは最初から知ってたよ君が世界で一番強い人なんだって"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_bercouli_1#originalText","id":"talk.vc.home_rank_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"剑法不错，有好好锻炼呢。","en":"Great form. I can tell you're training.","ja":"いい太刀筋だ鍛え上げてるな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_bercouli_2#originalText","id":"talk.vc.home_rank_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"我是觉得你的资质不错，但没想到成长得这么神速呢。","en":"I thought your form was improving... And it is. At an alarmingly fast rate.","ja":"筋が良いとは思っていたが恐ろしいほど早く成長してるな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_bercouli_3#originalText","id":"talk.vc.home_rank_bercouli_3","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"你很顺利地在变强呢。你就照这样超越我，然后继续前进吧。","en":"You just keep getting stronger and stronger. Keep it up and you’ll surpass me one day.","ja":"順調に強くなってるなその調子でオレを超えていってくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_bercouli_4#originalText","id":"talk.vc.home_rank_bercouli_4","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"没想到你会变得这么强。我真为你感到开心呢。","en":"I never imagined you'd actually become this powerful. I'm truly happy for you.","ja":"まさかこんなに強くなるとはなあ自分のことよりうれしいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_bercouli_5#originalText","id":"talk.vc.home_rank_bercouli_5","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"呼，我已经没什么话好说了。因为如今的你，恐怕连我都没得比了啊。","en":"Heh! There's nothing more for me to say. At your current level, even I can't beat you.","ja":"ふっ、もう何も言うことはない今のお前さんなら、オレもかなわないだろうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_cardinal_1#originalText","id":"talk.vc.home_rank_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你还真是可造之材。就照这样继续变强吧。","en":"You're proving to have potential. Keep at your training.","ja":"なかなか見どころのあるヤツじゃその調子で強くなれ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_cardinal_2#originalText","id":"talk.vc.home_rank_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你是不是稍微变剽悍啦？人类就是这样才有趣。","en":"Have you gotten a bit stronger? This is why I love humans. So amusing.","ja":"少したくましくなったか?これだから人間は面白い"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_cardinal_3#originalText","id":"talk.vc.home_rank_cardinal_3","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"你的表情变得精悍许多呢。这样一来，你或许可以匹敌集成骑士。","en":"The look in your eye is much more earnest now. Now you just might stand a chance against an Integrity Knight.","ja":"ちょっとは精悍な顔つきになったなそれならば整合騎士にも対抗できるかもしれん"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_cardinal_4#originalText","id":"talk.vc.home_rank_cardinal_4","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我也明白你有多强。真亏你能锻炼到这个地步。","en":"I, too, can see how strong you have become. I am proud of you.","ja":"わしにも、お主の強さはわかるよくぞここまで鍛え上げたものじゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_cardinal_5#originalText","id":"talk.vc.home_rank_cardinal_5","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我生平见过的最强人类，这个地位就在刚刚被你夺下了。","en":"Of all the humans I've encountered, you are now the strongest.","ja":"わしの見た中で、最も強い人間それは今、お主になった"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_deusolbert_1#originalText","id":"talk.vc.home_rank_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你越来越难对付了呢。我也不能够大意。","en":"You've become rather strong. I will have to keep on my toes.","ja":"なかなかに手強くなってきたな我も油断してはいられない"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_deusolbert_2#originalText","id":"talk.vc.home_rank_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你的剑法犀利，难以判读，在我看来是下了相当的苦心。","en":"Your sword movements are sharp and difficult to read. It is clear that you have trained well.","ja":"太刀筋が鋭く、読みにくい相当鍛えていると見た"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_deusolbert_3#originalText","id":"talk.vc.home_rank_deusolbert_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"那股力量……你有无打算为公理教会尽一份力？","en":"What power... I hope you intend to use it to serve the Axiom Church.","ja":"その力……公理教会のために役立てるつもりはないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_deusolbert_4#originalText","id":"talk.vc.home_rank_deusolbert_4","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"唔……虽然非我本意，但你的本事货真价实，连我都无法匹敌。","en":"Humph... Though it pains me to admit it, your powers are true. I can't compete.","ja":"くっ……不本意ではあるが貴様の腕は本物だ我でも敵わぬ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_deusolbert_5#originalText","id":"talk.vc.home_rank_deusolbert_5","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"或许，你已经登峰造极了啊……","en":"Perhaps you have climbed to the top of human potential.","ja":"あるいは貴様は、最たる高みに登ってしまったのかもしれないな……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_1#originalText","id":"talk.vc.home_rank_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"不错嘛。不过，你应该可以更好吧？","en":"Not bad. But, I know you can do better.","ja":"なかなかやるじゃないでも、あなたならもっとできるんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_2#originalText","id":"talk.vc.home_rank_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你那有办法努力不懈的态度，是最让我尊敬的。","en":"To be honest, I really respect your dedication and hard work.","ja":"あなたの、そういう努力を重ねられるところ、素直に尊敬するよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_3#originalText","id":"talk.vc.home_rank_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你成长许多呢……要不要来过个两招？","en":"You've come a long way... Would you like to spar with me?","ja":"ずいぶん成長したよね……一度、手合わせしてみる? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_4#originalText","id":"talk.vc.home_rank_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"真不愧是我看上的人，居然已经有这番成长了……","en":"Impressive. Just as I knew you would be. Look at how far you've come.","ja":"さすが、あたしの見込んだ人だねもうこんなに成長するなんて……"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_edith_5#originalText","id":"talk.vc.home_rank_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你完全符合最强这个词呢。这次就换我追着你跑了。","en":"Describing you as the ‘strongest’, it fits perfectly! Looks like I'll have to work hard to catch up to you.","ja":"あなたには最強って言葉がピッタリだね今度はあたしが追いかけるから"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eldrie_1#originalText","id":"talk.vc.home_rank_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您不懈的修行开花结果了呢。","en":"Looks like your training is paying off.","ja":"たゆまぬ修行の結実ですな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eldrie_2#originalText","id":"talk.vc.home_rank_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"在我看来，您的技术是越发纯熟了。","en":"I see your skills have improved.","ja":"技の冴えがますます上がっているようにお見受けいたします"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eldrie_3#originalText","id":"talk.vc.home_rank_eldrie_3","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我也必须致力修行以赶上您……我这为人子弟的可真丢人。","en":"I must train harder to keep up... As your mentor, I am embarrassed.","ja":"私も負けないように修行をせねば……弟子として恥ずかしい"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eldrie_4#originalText","id":"talk.vc.home_rank_eldrie_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"即使施展完全支配术，仍不知道自己能应战到何时……我从您身上感到如此惊人的力量。","en":"Even if I use Perfect Weapon Control, you could still hold your own in a fight for a while. That is just how much power I sense from you.","ja":"我が完全支配術を持ってしてもどのくらい戦っていられるか……それほどの力を感じます"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eldrie_5#originalText","id":"talk.vc.home_rank_eldrie_5","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"虽然您已经到了遥不可及的高处，我总有一天会跟您并驾齐驱的。","en":"You have now surpassed me greatly. However, I will be your equal once again someday.","ja":"はるか高みに上ってしまわれただが、私もいずれその傍らに並んでみせます"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_entokia_integrator_1#originalText","id":"talk.vc.home_rank_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"真是有趣的剑法，看老师使剑果然很有意思。","en":"Interesting fighting stance, eh, Master? I always get a kick out of watching you fight.","ja":"面白い剣筋っすなやっぱ先生の剣は見てて楽しいですわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_entokia_integrator_2#originalText","id":"talk.vc.home_rank_entokia_integrator_2","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"斩击果真锐利……要是挨到这招，绝大多数敌人肯定顿时毙命。","en":"An impressively sharp attack. You could knock out a whole horde of enemies in one blow.","ja":"さすがに鋭い斬撃……こんなん食らったら大抵の敵は一撃ですわ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_entokia_integrator_3#originalText","id":"talk.vc.home_rank_entokia_integrator_3","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"以老师的本事，说不定连我的剑枪《轰震枪》都能运用自如呢。","en":"If I were as strong as you, maybe I'd be able to wield my Roaring Thunder Spear properly.","ja":"その力があれば、もしかしたらオレの剣槍、《轟震槍》も使いこなせるかもしれないっすね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_entokia_integrator_4#originalText","id":"talk.vc.home_rank_entokia_integrator_4","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"哦……不愧是老师，真是精湛的剑法。哎呀，实在叫人敬佩。","en":"Whoa, Master! What impressive swordsmanship! For a moment, I didn't recognize you.","ja":"ほぉ……さすが先生見事な太刀筋ですいや、おみそれしました"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_entokia_integrator_5#originalText","id":"talk.vc.home_rank_entokia_integrator_5","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"到这地步，我想就算集成骑士一起上，或许也赢不过老师你呢。","en":"Even if the Integrity Knights ganged up against you, you still might defeat them, Master.","ja":"もう、整合騎士が束になってももしかしたら勝てないかもしれないっすね、先生には"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_1#originalText","id":"talk.vc.home_rank_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我们的状况都越来越好了呢。就照这样继续相互砥砺吧！","en":"We're both really getting into shape, huh? But, we need to keep getting stronger!","ja":"お互い、だいぶ調子が出てきたねこのまま高め合おう! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_2#originalText","id":"talk.vc.home_rank_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好惊人的奥义，你真的很厉害耶。我也要变得更强才行。","en":"Wow! Those were some impressive moves! I need to keep training.","ja":"すごい奥義だね、さすがだよ僕も、もっと強くならないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_3#originalText","id":"talk.vc.home_rank_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你果然很强呢。希望我可以进步到比三次能赢你一次啊。","en":"You're strong, just like I thought. I'd like to at least win 1 out of 3 matches!","ja":"さすがに強いねせめて3本に1本くらいは取れるようになりたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_4#originalText","id":"talk.vc.home_rank_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"唔……你什么时候变得这么强了啊？我们之间的实力差距，可能已经被拉得很开了呢。","en":"Oof...since when did you get this strong? The gap between our levels has widened a lot.","ja":"くっ……いつの間にこんな力をもう、ずいぶん差が開いちゃったかもしれないな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_5#originalText","id":"talk.vc.home_rank_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"真不愧是我的师父。不过，我总有一天也会成长到那个境界的。","en":"That's why you're my trainer! But I promise I'll catch up to you someday.","ja":"さすが僕の師匠だよでも、僕もいつかその場所まで行ってみせるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_child_1#originalText","id":"talk.vc.home_rank_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你该不会偷偷在练剑吧？你挥斧头的方式变得俐落很多耶。","en":"Wait a minute, have you been practicing sword fighting in secret? Your axe swinging is a bit weak.","ja":"もしかして、こっそり剣の稽古とかしてる? 斧の振り方が鋭くなってるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_child_2#originalText","id":"talk.vc.home_rank_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"不知不觉间，你变厉害了呢。我也要加油，才不会被你抛下。","en":"You got a lot stronger while I wasn't looking. I'd better step up so I don't get left behind.","ja":"いつの間にか、強くなっちゃったね僕も置いていかれないようにしないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_child_3#originalText","id":"talk.vc.home_rank_eugeo_child_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你稍微长高了呢。嗯……我也要更加锻炼才行了。","en":"Your muscles have gotten a little bigger. Hmmm...I'd better train harder.","ja":"ちょっと体が大きくなったねうーん……僕も、もっと鍛えないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_child_4#originalText","id":"talk.vc.home_rank_eugeo_child_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我也要仔细思考，该怎么做才能变得那么强。","en":"How can I get stronger like you? I'll need to think about that.","ja":"どうしたらそんなに強くなれるか僕もちゃんと考えないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_eugeo_child_5#originalText","id":"talk.vc.home_rank_eugeo_child_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"虽然我一直追着你的背影，但始终追不上呢。你真厉害。","en":"I've been struggling to keep up with you all this time, but I can never fully catch up.","ja":"ずっと背中を追いかけてきたけどなかなか届かないよさすがだな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fanatio_1#originalText","id":"talk.vc.home_rank_fanatio_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您还没拿出真本事吧？我想早日看到您真正的实力。","en":"You still aren't taking this seriously, are you? I want to see your full potential soon.","ja":"まだ本気ではありませんね?早く本気が見たいものです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fanatio_2#originalText","id":"talk.vc.home_rank_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"果然是很锐利的一击……我也想要学习。","en":"Very sharp attacks indeed. I could learn a thing or two from you.","ja":"やはり鋭い打ち込み……私も見習いたいと思います"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fanatio_3#originalText","id":"talk.vc.home_rank_fanatio_3","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"果然厉害。我想没多少骑士像您这么有本事。","en":"I am impressed. Not many knights have your skill.","ja":"さすがですそれほどの腕を持つ騎士はそうはいないでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fanatio_4#originalText","id":"talk.vc.home_rank_fanatio_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您是强到我无力抗衡了……不过，我也总有一天会追上您的！","en":"Your strength cannot be matched... even by myself... But someday, I will catch up to you!","ja":"私などは到底太刀打ちできない強さ……ですが、私もいつか追いつきます!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fanatio_5#originalText","id":"talk.vc.home_rank_fanatio_5","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"能持续进行如此令人却步的大量修练，我为您的精神力深表佩服。","en":"You must have trained your body so hard that your mind reached a meditative state I truly admire your strong will!","ja":"気が遠くなるほどの修練それを続ける精神力に感服いたします"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fizel_1#originalText","id":"talk.vc.home_rank_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"你好像稍微变强了呢。不过，还是我比较强啦。","en":"I see you've gotten a bit stronger. But I'm still more powerful than you.","ja":"ちょっとは強くなったみたいねでも、まだあたしの方が強いわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fizel_2#originalText","id":"talk.vc.home_rank_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"嗯～看起来很强嘛。你一定比那些路边常见的骑士大人还厉害呢。","en":"Oooh, you look pretty tough. I'm sure you're stronger than the average Integrity Knight.","ja":"ふーん、強そうじゃないそこらにいる騎士様よりはきっと腕が立つわね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fizel_3#originalText","id":"talk.vc.home_rank_fizel_3","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"哼、哼！你可别因为稍微变强了点，就跑来跟我炫耀喔！","en":"Hmph! Don't pose and strut just because you've put on a little muscle!","ja":"ふ、ふん!ちょっと強くなったからって自慢しないでよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fizel_4#originalText","id":"talk.vc.home_rank_fizel_4","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"……嗯，好像比我还强了。唔～真不甘心！","en":"Yeah...you're even stronger than I am now. Grrr, how vexing!","ja":"……うん、あたしよりも強そううー、くやしい!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_fizel_5#originalText","id":"talk.vc.home_rank_fizel_5","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"再怎么看，我好像都没有胜算了。不过我觉得，你比不上亚多米尼史特蕾达大人。","en":"Yes, now I could never defeat you. But the Lady Administrator could.","ja":"さすがに、もう勝てそうにないわでも、アドミニストレータ様には負けると思うけど"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_iskahn_1#originalText","id":"talk.vc.home_rank_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"呵，这种程度……我一拳就能收拾掉了。更努力锻炼吧！","en":"Ha, at that rate... I can take you down with one punch! You need to get even stronger!","ja":"ふん、その程度……俺の拳一発で倒せるぜもっともっと鍛えろ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_iskahn_2#originalText","id":"talk.vc.home_rank_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"还完全不够。你心目中的强大应该不止这样吧。","en":"This is still far from enough! You need to aim even higher levels of strength.","ja":"まだまだ、全然足りねえもっと上だろ、お前が目指す強さってのは"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_iskahn_3#originalText","id":"talk.vc.home_rank_iskahn_3","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"总算变得有点看头了。就算对手是我，也应该可以撑过几下攻击吧。","en":"Looks like you can see a little better. If I were to be your opponent, you could probably take a couple of punches from me.","ja":"少しは見られるようになってきたな俺が相手でも、数発は耐えられるかもしれねえ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_iskahn_4#originalText","id":"talk.vc.home_rank_iskahn_4","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"做得不错嘛。我就知道是你的话一定可以到达这里。","en":"I knew you had it in you! There was no doubt in my mind you would make it this far.","ja":"やるじゃねえかお前なら、きっとここまで来ると思ってたぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_iskahn_5#originalText","id":"talk.vc.home_rank_iskahn_5","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我就坦然承认你的强大吧。但是，我也会变强。到时候再分胜负吧，一定要喔！","en":"I acknowledge your strength. But, I will still get stronger! When that happens, we will fight! You can count on that.","ja":"お前の強さ、素直に認めようだが、俺もまだ強くなるその時は勝負だ、必ずな!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_1#originalText","id":"talk.vc.home_rank_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"哦！你的身体最近是不是变结实啦？","en":"Whoa! Is it just me, or have you been getting jacked?","ja":"お! 最近、身体引き締まってきたんじゃないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_2#originalText","id":"talk.vc.home_rank_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你的剑技变得很像样了呢。我也不能输啊。","en":"Your form is getting really good. Guess I need to up my game.","ja":"剣筋が様になってきたな俺も負けてられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_3#originalText","id":"talk.vc.home_rank_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"最近你的表情越来越有剑士的样子了！我是在称赞你啦！","en":"You've been looking like a real swordsman lately! That's a compliment, believe me!","ja":"最近顔つきが剣士って感じになってきたぞ!褒めてるんだって!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_4#originalText","id":"talk.vc.home_rank_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"上次的练习都是你赢啊！不过今天可不会再重演了！","en":"You totally won the last match. But I'm not letting that happen again today!","ja":"前回の稽古は完全にそっちの勝ちだったな!今日はそうは行かないけどな!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_5#originalText","id":"talk.vc.home_rank_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我已经没东西好教了呢。我以你为荣。","en":"I have nothing left to teach you. You should be proud of yourself.","ja":"もう俺が教えることは何ひとつないな誇りに思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_child_1#originalText","id":"talk.vc.home_rank_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你最近变强了呢。好，我也不会输！","en":"You've gotten stronger recently. Okay! Looks like I need to up my game!","ja":"最近強くなったよなよーし、俺も負けないぞ! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_child_2#originalText","id":"talk.vc.home_rank_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我们现在应该，赢得过外面的魔兽了吧？","en":"Don't you think we've gotten strong enough to hold our own against the beasts out there?","ja":"そろそろ、俺たちでも外の獣に勝てるようになったんじゃないか? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_child_3#originalText","id":"talk.vc.home_rank_kirito_child_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……你是不是变高啦？可恶，居然偷长！","en":"Hey...did you get taller? Darn it! You're beating me!","ja":"……なんか、背が伸びたか? くっそー、抜け駆けしやがって! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_child_4#originalText","id":"talk.vc.home_rank_kirito_child_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"只要像这样继续变强，就连砍倒那棵大树也不是梦！","en":"If we keep training like this, cutting down that big tree won’t just be a far-fetched dream!","ja":"こうやって強くなっていけばあのでかい木を倒すのだって夢じゃないよな! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kirito_child_5#originalText","id":"talk.vc.home_rank_kirito_child_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你真的变强了呢。就好像真正的剑士一样！真厉害！","en":"You really have gotten really strong. I'm impressed! You're just like a real swordsman.","ja":"本当に強くなったなまるで本物の剣士みたいだ! さすがだよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_klein_1#originalText","id":"talk.vc.home_rank_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"喔，你升级啦？很行嘛。","en":"Ooh! You leveled-up? Not too shabby, dude.","ja":"お、レベルが上がったのか?なかなかやるじゃねーか"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_klein_2#originalText","id":"talk.vc.home_rank_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你很强耶。可是，我也不输你喔。","en":"Dang, you're strong! But not as strong as me!","ja":"やっぱ強えな、オメエはでも、オレも負けてないぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_klein_3#originalText","id":"talk.vc.home_rank_klein_3","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"喂喂，你又升级了喔？也太快了吧。","en":"Whoa, dude, you leveled up again? A little fast, don't you think?","ja":"おいおい、またレベルアップかよどんだけ早いんだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_klein_4#originalText","id":"talk.vc.home_rank_klein_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你已经变得这么强啦……你还是那么严格要求自己呢。","en":"Jeez, already so strong? Even in this world, you're just as stoic as ever.","ja":"もうこんなに強いのかよ……相変わらずストイックだなオメエは"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_klein_5#originalText","id":"talk.vc.home_rank_klein_5","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"恭喜。对于你的本事，我已经没什么好说的啦。","en":"Congrats, man. I'll never joke about how weak you are again.","ja":"おめでとさんもう、オメエの強さには何も言うことはないぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kureha_1#originalText","id":"talk.vc.home_rank_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"升级了呢。但是，光是这样还打不倒我喔。","en":"Looks like you ranked up! But, even at that level you won't beat me.","ja":"ランクアップしたのねでも、そのくらいじゃまだまだあたしは負けないな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kureha_2#originalText","id":"talk.vc.home_rank_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"非常精确的攻击……我也得学学你的那个动作才行。","en":"Such an accurate attack... I must learn that move.","ja":"すごく正確な攻撃……その動きは、見習わないと"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kureha_3#originalText","id":"talk.vc.home_rank_kureha_3","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"……嗯，你变得好强喔。虽然我也对自己很有自信，不过，不知道赢不赢的过你。","en":"...Yes, you've gotten quiet strong, I see. I have confidence in myself, but in terms of if I'll win...","ja":"……うん、すごい強くなったねあたしだって自信はあるけどでも、勝てるかどうか"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kureha_4#originalText","id":"talk.vc.home_rank_kureha_4","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"你真的好厉害啊……但是，我也会努力不要输给你的！","en":"You really are an amazing one... But that doesn't I'll give up so easily!","ja":"やっぱりすごいな……でも、あたしだって負けないように頑張るから!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_kureha_5#originalText","id":"talk.vc.home_rank_kureha_5","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"真不愧是你。下次战斗的时候，我会用和高手讨教的心态和你对战的！","en":"No surprise there! I'll make sure to have you on my side in the next battle!","ja":"さすがだね今度戦うときは、胸を借りるつもりでぶつかるから!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_leafa_1#originalText","id":"talk.vc.home_rank_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你升级了呢！好厉害！大概是练习的成果浮现了吧？","en":"Your rank went up! Way to go! All that training paid off.","ja":"ランクアップ、さすがだね! 練習の成果が出てるんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_leafa_2#originalText","id":"talk.vc.home_rank_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"好厉害～你已经变得那么强了啊？","en":"Wow! How'd you get so strong so fast?","ja":"すごーい、もうそんなに強くなったの? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_leafa_3#originalText","id":"talk.vc.home_rank_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你今天的表现很棒呢，我也不能输啊。","en":"You moved really well today. I need to up my game.","ja":"今日の動き、すごかったねあたしも負けてられないな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_leafa_4#originalText","id":"talk.vc.home_rank_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"讨厌，真是比不过你。你完全是大家的队长了呢！","en":"Man, no one can hold a candle to you anymore. You're totally our leader!","ja":"もう、ちょっと敵わないかなあすっかりみんなのリーダーだよね! "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_leafa_5#originalText","id":"talk.vc.home_rank_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这就是所谓的高手吧？动作优美又俐落……我要跟你看齐呢。","en":"Is this what a master looks like? Your moves are almost like dancing... O, teach me your ways!","ja":"達人ってこういうことなのかな動きがキレイで無駄がなくて……見習いたいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_linel_1#originalText","id":"talk.vc.home_rank_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你变强了呢……我也想变强，然后早点成为正式的集成骑士。","en":"You've gotten stronger, I see. I hope to become stronger, too, so I can become a proper Integrity Knight.","ja":"強くなったんですね……私も強くなって、早く正式な整合騎士になりたいです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_linel_2#originalText","id":"talk.vc.home_rank_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你那么强，一定有办法跟集成骑士对战呢。","en":"At your current level, you can certainly hold your own against an Integrity Knight.","ja":"その強さなら、きっと整合騎士とも戦えますね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_linel_3#originalText","id":"talk.vc.home_rank_linel_3","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"要杀了多少，才能变得那么强呢？","en":"How many more must I kill to become as strong as you?","ja":"どのくらい殺せばそれだけ強くなれるんでしょう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_linel_4#originalText","id":"talk.vc.home_rank_linel_4","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我都认不出你了。你一定是进行了很多锻练，才变得这么强吧。","en":"My mistake. You surely trained very hard to become that strong.","ja":"見違えちゃいましたきっと、たくさん鍛えて強くなったんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_linel_5#originalText","id":"talk.vc.home_rank_linel_5","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"你那么强，一定也能战胜守护龙吧。我好憧憬你。","en":"At your level, you might even be able to defeat a guardian dragon. Oh, how I envy you.","ja":"その強さなら、きっと守護竜にも勝ってしまうんでしょうね憧れます"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_lisbeth_1#originalText","id":"talk.vc.home_rank_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你升级了吗？那你……要不要试一下这个装备？","en":"You climbed up in rank? Okay then, wanna test out this equipment?","ja":"ランクアップしたの? じゃあさ、この装備……試してみない? "},"kind":"dialogue"},{"uid":"talk.vc.home_rank_lisbeth_2#originalText","id":"talk.vc.home_rank_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喔～真厉害。一眨眼的功夫就变强了。","en":"Hmmm. Well, look at you. Got all strong while my back was turned.","ja":"ふーん、さすがねあっという間に強くなっちゃって"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_lisbeth_3#originalText","id":"talk.vc.home_rank_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"哦喔，你变强啦。其实啊，我想去某个任务，但敌人太强了～","en":"Oh, yes, yes, you've gotten much stronger. Funny, seeing as how this quest just popped up that I want to go on, but the enemies are too powerful for meee...","ja":"ほうほう、強くなったんだ実はね、行きたいけど敵が手強いクエストがあるのよねー"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_lisbeth_4#originalText","id":"talk.vc.home_rank_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"因为你一直有在锻炼嘛，所以我觉得变强是天经地义的事。恭喜你。","en":"Well, after all that hard training, of course you got stronger. Congrats.","ja":"ずっと鍛錬してたもんね強くなって、当然だと思うおめでとう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_lisbeth_5#originalText","id":"talk.vc.home_rank_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"总有一天，要再让我帮你量身打造一把剑。我们约好啰。","en":"Let me make you a custom sword again someday. Promise me.","ja":"いつか、あんたにぴったりの剣をもう一度作らせて約束よ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_medina_1#originalText","id":"talk.vc.home_rank_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你的剑法稍微进步了呢。但是，还是不够成熟，你自己也应该很清楚吧。","en":"Your swordsmanship has improved a little. But you still have things you need to work on. You got that, right?","ja":"少しはいい剣筋になったなだが、まだまだ未熟だお前にもわかっているだろうがな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_medina_2#originalText","id":"talk.vc.home_rank_medina_2","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"哼，很不错的剑法。在下次比剑之前，再锻炼一下招式会比较好！","en":"Hmm. This sword's not too bad. Next time we face each other, it would be smart to sharpen up those skills!","ja":"ふん、なかなかの剣だ次に立ち合う時までもっと技を磨いておいた方がよいぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_medina_3#originalText","id":"talk.vc.home_rank_medina_3","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"不知不觉间，你居然拥有了这么强大的力量……我也不能输，马上追到和你不分上下！","en":"All of a sudden, where did that power come from...? There's no way I can lose! Hurry up and challenge me!","ja":"いつの間に、そんな力を……私も負けていられないすぐに肩を並べてやる!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_medina_4#originalText","id":"talk.vc.home_rank_medina_4","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"虽然不甘心，但你所拥有的力量是货真价实的。也就是说，你拥有的心意也是真的。","en":"It's unfortunate, but your power is the real deal. That means your sentiment is also real.","ja":"悔しいが、お前の力は本物だお前の持つ想いも、本物だったということだな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_medina_5#originalText","id":"talk.vc.home_rank_medina_5","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"这个世界上一定再也没有像你这样厉害的剑士了。我就老实的称赞你吧。","en":"There is no swordsman of your caliber in this world. Let's take a moment to seriously admire that.","ja":"お前ほどの剣士はこの世界にはきっといない素直に賞賛しよう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_nergius_integrator_1#originalText","id":"talk.vc.home_rank_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"才这点本事就想夸耀自己的剑技，你应该不是真心认为自己很行吧？","en":"Do you honestly take pride in your mediocre sword skills? You cannot be serious.","ja":"その程度で剣を誇ろうなどまさか本気で思っているのではないでしょうな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_nergius_integrator_2#originalText","id":"talk.vc.home_rank_nergius_integrator_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"确实是值得一睹的剑法，看得到修练的成果。","en":"Your fighting stance has indeed improved. A testament to hours of dedicated practice.","ja":"確かに、見るべき剣筋だ修練の成果が見える"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_nergius_integrator_3#originalText","id":"talk.vc.home_rank_nergius_integrator_3","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"代表剑士……你终于获得不负此名的剑了。","en":"Swordsman Delegate... At last, you have received a sword worthy of your title.","ja":"代表剣士……ようやくその名にふさわしい剣を手に入れましたな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_nergius_integrator_4#originalText","id":"talk.vc.home_rank_nergius_integrator_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"人竟然能变得如此强大……老实说，我现在依然无法置信。","en":"To be honest, it still surprises me, even now, just how strong a person can become.","ja":"人がこれほど強くなるとは……正直、未だに信じられませぬ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_nergius_integrator_5#originalText","id":"talk.vc.home_rank_nergius_integrator_5","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"原来如此，甘拜下风。我涅鲁基乌斯，愿将此剑献给你。","en":"I see. Forgive me. I, Nergius, shall pledge my sword to you.","ja":"なるほど、恐れ入ったこのネルギウス、あなたの下に剣を捧げましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_phillia_1#originalText","id":"talk.vc.home_rank_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"呵呵，我知道，你还会变得更更更强喔！","en":"Fufu, I just know that you'll get even stronger.","ja":"ふふ、あなたはもっともっと強くなるって、わたしは知ってるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_phillia_2#originalText","id":"talk.vc.home_rank_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"嗯，我觉得你变强了。但是，你不只如此吧？","en":"I do think you've gotten quiet strong. However, you're not quiet there yet.","ja":"うん、すごく強くなってると思うでも、こんなもんじゃないよね?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_phillia_3#originalText","id":"talk.vc.home_rank_phillia_3","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"你果然很可靠。但是，我也不能一直依赖你。","en":"I guess I can count on you afterall. But, I don't need someone to only rely on.","ja":"やっぱり頼りになるなあでも、わたしも頼ってばかりじゃいられないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_phillia_4#originalText","id":"talk.vc.home_rank_phillia_4","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"毕竟你一直在锻炼自己嘛。这份强大就是锻炼的证明。","en":"You've really been training this whole time. That strength of yours, is proof of it.","ja":"ずっと自分を鍛えてきたもんねその証だよ、この強さは"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_phillia_5#originalText","id":"talk.vc.home_rank_phillia_5","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"从你救了我的那一刻，你就一直是我心里的一部分……因为是断片啊。","en":"Since the time when you rescued me, you've been a part of me... A fragment of me.","ja":"わたしを救ってくれたときからずっとあなたはわたしの一部……フラグメントだから"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_premiere_1#originalText","id":"talk.vc.home_rank_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"恭喜升级！朝向下个等级继续努力吧！","en":"Congratulations on ranking up. Let's keep doing our best for the next round.","ja":"ランクアップおめでとうございます次を目指して頑張りましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_premiere_2#originalText","id":"talk.vc.home_rank_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"恭喜升级。奖励要用什么食物比较好呢？","en":"Congratulations on ranking up. What kind of meal would you like to celebrate this special occasion?","ja":"ランクアップおめでとうございますご褒美はどんなご飯がいいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_premiere_3#originalText","id":"talk.vc.home_rank_premiere_3","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"我听说达到这个等级的人不多。你真的很强呢。","en":"I've never heard of anyone ranking up that high before. You're quiet the strong one, aren't you.","ja":"このランクまで上がる人は、それほど多くないと聞きましたあなたはとても強いのですね"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_premiere_4#originalText","id":"talk.vc.home_rank_premiere_4","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"明明是你变强了，但不知为何我也觉得有点骄傲。……究竟是为什么呢？","en":"Seeing you get this strong, makes me a bit proud ...I wonder why?","ja":"あなたが強くなると、どうしてか私も少し誇らしい気分になります……なぜでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_premiere_5#originalText","id":"talk.vc.home_rank_premiere_5","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"我已经无法衡量你的强大了。这让我感到非常……开心。","en":"I can't measure your strength anymore. That makes... me so happy.","ja":"もう、私にはあなたの強さを測ることはできませんそれが、とても……うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_rain_1#originalText","id":"talk.vc.home_rank_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"喔－－，原来也有那种动作啊。呐，下次可以教我吗？","en":"Hey, when did you get that move? Would you mind teaching it to me next time?","ja":"へぇー、そういう動きもあるんだねえ、今度教えてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_rain_2#originalText","id":"talk.vc.home_rank_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"真不愧是你，很快就熟练了呢。我也不能输给你！","en":"Just as I suspected, you leveled up pretty fast. I'll make sure I won't lose!","ja":"さすがに上達が早いわねわたしも負けてられない!"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_rain_3#originalText","id":"talk.vc.home_rank_rain_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你升那么多级了吗？真是的，什么时候变那么强的？","en":"Wow! How'd you get so strong so fast? ","ja":"もうそんなにランクアップ?まったく、いつの間にそんなに強くなってるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_rain_4#originalText","id":"talk.vc.home_rank_rain_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"真不愧是你，果然很强啊……一对一已经对付不了你了呢。","en":"As anticipated, you're a strong one... There's no way that I can do one-on-one combat with you.","ja":"さすがに強いわね……もう、一騎打ちではちょっと太刀打ちできないかな"},"kind":"dialogue"},{"uid":"talk.vc.home_rank_rain_5#originalText","id":"talk.vc.home_rank_rain_5","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你的强大，一定也是内心的强大吧。","en":"Not only do you have physical strength, but a strong heart as well.","ja":"あなたの強さは、きっと心の強さでもあるんだね"},"kind":"dialogue"}]};
